def chapter(id, group, title, lead, body, keywords=""):
    return dict(id=id, group=group, title=title, lead=lead, body=body, keywords=keywords)


CHAPTERS = [
chapter("overview", "Начало работы", "Знакомство с ПарДозором",
"Что умеет прибор, где находятся органы управления и с чего начать.", r"""
<div class="intro-grid"><div><p>ПарДозор — прибор для контроля и автоматики перегонки и ректификации. Он объединяет до четырёх температурных каналов, этапы процесса, оповещения, график и журналы. С подключённым клапаном управляет отбором, с весами показывает массу, расчётный объём и скорость.</p><p>Работать можно с экрана 2″ или через браузер телефона, планшета и компьютера. Интернет для измерения и автоматики не требуется.</p></div><figure><a href="assets/controller.jpg" target="_blank" rel="noopener"><img src="assets/controller.jpg" alt="Реальный ПарДозор в зелёном корпусе: экран, кнопка и энкодер" width="800" height="600"></a><figcaption>Реальный прибор на колонне. Фото увеличивается по нажатию.</figcaption></figure></div>
<h2>Сначала — три важных различия</h2><dl class="definitions"><div><dt>Процесс</dt><dd>Текущая последовательность этапов и их настроек.</dd></div><div><dt>Шаблон</dt><dd>Отдельно сохранённый набор настроек, из которого можно создать текущий процесс.</dd></div><div><dt>Сеанс</dt><dd>Номер записи конкретного запуска/работы, по которому группируются измерения и события.</dd></div></dl>
<h2>Карта возможностей</h2><div class="table-wrap"><table><thead><tr><th>Возможность</th><th>Как пользоваться</th></tr></thead><tbody><tr><td>До 4 температур DS18B20</td><td><a href="#sensors">Роли и названия</a>, <a href="#temperature">контроль отклонений</a>, <a href="#calibration">поправки по ROM</a>.</td></tr><tr><td>Процессы и этапы</td><td><a href="#templates">7 шаблонов</a>, <a href="#stages">до 10 этапов</a>, <a href="#self-reflux">работа на себя</a>.</td></tr><tr><td>Клапан отбора</td><td><a href="#valve">3 режима управления</a>, <a href="#pwm">импульсный отбор</a>, <a href="#reduction">снижение после остановки</a>.</td></tr><tr><td>Весы</td><td><a href="#scales">Калибровка и тара</a>, <a href="#target">объём, скорость и цель</a>.</td></tr><tr><td>История и сервис</td><td><a href="#history">Журналы и экспорт</a>, <a href="#report">отчёт</a>, <a href="#diagnostics">диагностика</a>, <a href="#update">обновление</a>.</td></tr><tr><td>Повседневная работа</td><td><a href="#wifi">Сохранённые Wi-Fi сети</a>, <a href="#local">локальное меню</a>, <a href="#calculator">калькулятор</a>.</td></tr></tbody></table></div>
<h2>Границы возможностей</h2><p>Прибор не управляет нагревателем, не измеряет крепость автоматически и не интегрирован с умной розеткой или приводом крана воды. Весы не закрывают клапан при достижении цели. Один настроенный температурный канал управляет одним выходом клапана; названия других каналов сами по себе не назначают им управляющие функции.</p>
<div class="callout"><strong>Первый раз включаете прибор?</strong><p>Начните с <a href="#safety">условий безопасной работы</a>, затем выполните <a href="#quick-start">первый запуск</a>. Эта инструкция описывает интерфейс прошивки 0.5.0-dev.104. Если меню отличается, посмотрите версию внизу главной страницы или в диагностике.</p></div>
""", "назначение возможности комплект экран контроллер инструкция руководство"),

chapter("safety", "Начало работы", "Перед подключением и работой",
"Что проверяет автоматика и что остаётся под контролем оператора.", r"""
<div class="callout warning"><strong>ПарДозор не отключает нагрев.</strong><p>При остановке отбора нагрев и охлаждение продолжают работать по настройкам самого аппарата. Реагируйте на ситуацию по инструкции к аппарату. Не используйте ПарДозор как единственную защиту или основание оставить установку без наблюдения.</p></div>
<h2>Перед первым включением</h2><ol class="steps"><li>Проверьте маркировку питания и используйте комплектный либо согласованный с изготовителем блок питания.</li><li>Подключите штатные датчики и дополнительные модули при выключенном питании. Не подавайте напряжение сети на низковольтные разъёмы.</li><li>Установите контроллер и кабели вдали от проливов, горячих поверхностей и мест, где их можно выдернуть. Не допускайте попадания жидкости в корпус.</li><li>Проверьте механическую исправность клапана, трубок и весов. Надпись «Открыт» сообщает о команде на выходе, а не о фактическом положении механизма.</li><li>Проверьте контроль и переключение клапана на холодной установке до рабочего процесса. Подключённый клапан должен быть нормально закрытым.</li></ol>
<h2>Питание и USB</h2><p>Одновременное питание платы от USB и внешнего блока для текущей сборки не подтверждено. Перед подключением USB-UART для восстановления отключите внешний блок и питание клапана. Не меняйте внутреннюю проводку и силовую часть по этой пользовательской инструкции.</p>
<h2>Поведение клапана</h2><ul><li>После перезагрузки выход закрыт до явного действия оператора. Начало нового сеанса и выбор этапа — такие действия: они могут применить открывающий режим этапа.</li><li>Температурный контроль закрывает клапан только при соответствующей автоматике этапа. Режим «Открыть вручную» не подчиняется температуре, ошибкам датчика и ШИМ.</li><li>Режим этапа «Всегда открыт» не является температурной защитой. В нём отбор разрешён независимо от опорной температуры.</li><li>При потере Wi-Fi автономные измерения и управление продолжаются. Исчезнувший экран браузера не означает закрытие клапана.</li><li>Отключение звука тревоги не устраняет её причину и не меняет режим клапана.</li></ul>
<h2>Если поведение неожиданное</h2><p>Сначала обеспечьте безопасное состояние установки физическими средствами. Затем проверьте <a href="#valve">режим клапана</a>, <a href="#alarms">причину тревоги</a> и <a href="#diagnostics">диагностику</a>. Не пытайтесь компенсировать неисправность датчика увеличением поправки или допуска.</p>
""", "безопасность питание usb нагрев ТЭН охлаждение ручной клапан"),

chapter("quick-start", "Начало работы", "Первый запуск: пошагово",
"Подключитесь к прибору и проверьте показания до включения автоматики.", r"""
<ol class="steps"><li><strong>Подключите датчики.</strong> При выключенном питании вставьте по одному штатному DS18B20 в нужные входы. Запомните, какой зонд установлен в каком узле.</li><li><strong>Включите питание.</strong> Дождитесь отрисовки экрана. Убедитесь, что выводится версия/процесс и ожидаемые температуры. Клапан после загрузки закрыт.</li><li><strong>Найдите сеть устройства.</strong> Если домашняя сеть ещё не задана, подключите телефон к <code>ColumnSensor-XXXX</code>. Пароль: <code>column-setup</code>. Отсутствие интернета в этой сети нормально. Не разрешайте телефону автоматически уйти на другую Wi-Fi сеть.</li><li><strong>Откройте интерфейс.</strong> В адресной строке браузера наберите <code>http://192.168.4.1/</code>. Это адрес прибора в собственной сети, а не адрес публичного сайта инструкции.</li><li><strong>Проверьте каналы.</strong> В карточке каждого датчика откройте «Управление и параметры», задайте название и роль, нажмите «Сохранить параметры». Для клапана отдельно отметьте один канал «Управляет клапаном 1».</li><li><strong>Выберите задачу.</strong> В блоке «Текущий процесс» выберите сохранённый шаблон и подтвердите. Для знакомства без управления отбором используйте «Наблюдение».</li><li><strong>Проверьте готовность.</strong> Откройте «Подготовка и проверка», проверьте датчики и тестовый звук. Физические проверки выполните самостоятельно.</li><li><strong>Настройте связь с роутером при необходимости.</strong> На странице «Wi-Fi» сохраните сеть 2,4 ГГц и подключитесь к ней. Верните телефон в эту же сеть и откройте <code>http://pardozor.local/</code> либо IP с экрана.</li></ol>
<div class="callout success"><strong>Первый запуск завершён, если</strong><p>видны ожидаемые датчики, роли соответствуют установке, клапан находится в известном состоянии, интерфейс обновляется, а тестовый зуммер слышен. Для температурной автоматики дополнительно нужны опорная температура и параметры контроля.</p></div>
<h2>Не торопитесь фиксировать опорную</h2><p>Текущая температура становится опорной после нажатия «Зафиксировать температуру». Во время разогрева это обычно не нужная рабочая точка. Сначала дождитесь предусмотренного вашим процессом состояния и проверьте <a href="#temperature">рабочее окно</a>.</p>
<h2>После первого запуска</h2><p>Сохраните нужные <a href="#templates">шаблоны</a>, при необходимости откалибруйте <a href="#calibration">датчики</a> и <a href="#scales">весы</a>. Перед реальным применением отдельно проверьте автоматическое закрытие и восстановление клапана на холодной установке.</p>
""", "включение 192.168.4.1 column-setup подключить телефон старт"),

chapter("dashboard", "Начало работы", "Главная страница и навигация",
"Как читать показания и где искать настройки, историю и сервисные функции.", r"""
<h2>Сверху вниз</h2><dl class="definitions"><div><dt>Шапка</dt><dd>Название прибора, включение звука браузера и подтверждение/отключение звука тревоги.</dd></div><div><dt>Текущий процесс и этап</dt><dd>Выбор сохранённого процесса, название этапа и следующего этапа, переход, таймер работы на себя. При включённой ШИМ — текущий процент, цикл и состояние.</dd></div><div><dt>Клапан отбора</dt><dd>Фактическая команда выхода, причина закрытия и выбор ручного управления либо автоматики этапа.</dd></div><div><dt>Вес отбора</dt><dd>Показывается при включённых весах: масса, расчётный объём, скорость, цель и прогноз.</dd></div><div><dt>Температурные каналы</dt><dd>Температура, состояние контроля, стабильность, опорная и отклонение. Настройки раскрываются внутри карточки.</dd></div><div><dt>График и журнал устройства</dt><dd>Температуры текущей доступной истории, последние события и кнопка «Экспорт журнала».</dd></div></dl>
<h2>Ссылки внизу главной страницы</h2><div class="table-wrap"><table><thead><tr><th>Ссылка</th><th>Что открывает</th></tr></thead><tbody><tr><td>Подготовка и проверка</td><td>Помощник <code>/assistant</code>.</td></tr><tr><td>История показаний</td><td>Таблицу и полный экспорт <code>/assistant#history</code>.</td></tr><tr><td>Отчёт сеанса</td><td>Сбор отчёта по кнопке <code>/assistant#report</code>.</td></tr><tr><td>Настройки</td><td>Общие настройки и поправки датчиков <code>/settings</code>.</td></tr><tr><td>Настройка температурных этапов и шаблонов</td><td>Отдельную страницу <code>/process</code>.</td></tr><tr><td>Калькулятор / Диагностика / Wi-Fi / Обновление</td><td><code>/calculator</code>, <code>/diagnostics</code>, <code>/wifi</code>, <code>/update</code>.</td></tr></tbody></table></div>
<h2>Свежесть данных</h2><p>При единичном пропуске обновления появляется «задержка обновления». После нескольких ошибок или длительного отсутствия данных — «Нет связи». Последние числа на экране не следует считать текущими. Локальный экран и автоматика могут при этом продолжать работать.</p>
<h2>Инструкция и интерфейс прибора — разные сайты</h2><p>Этот сайт на GitHub — справочник. Он не подключается к оборудованию и не меняет настройки. Для управления откройте локальный адрес своего прибора, находясь в одной сети с ним. Публичное демо по отдельной ссылке также не управляет вашим прибором.</p>
""", "главная меню кнопки ссылки график где настройки нет связи"),

chapter("local", "Начало работы", "Экран, энкодер и отдельная кнопка",
"Основные действия доступны без телефона и без домашнего Wi-Fi.", r"""
<figure class="figure-small"><a href="assets/display.jpg" target="_blank" rel="noopener"><img src="assets/display.jpg" alt="Экран ПарДозора крупным планом" width="600" height="800" loading="lazy"></a><figcaption>Реальное фото экрана. Подписи на старом снимке могут отличаться от текущей версии.</figcaption></figure>
<h2>Два органа управления</h2><ul><li><strong>Вращение энкодера:</strong> на главном экране выбирает датчик, в меню — пункт, в числовом редакторе — значение.</li><li><strong>Нажатие энкодера:</strong> открывает меню, выбирает действие, сохраняет число. В окне подтверждения означает «Да».</li><li><strong>Отдельная кнопка:</strong> в меню возвращает назад или отменяет действие. На главном экране сначала подтверждает активное оповещение; если его нет и клапан открыт — закрывает его вручную.</li></ul>
<div class="callout warning"><strong>Кнопка зависит от контекста.</strong><p>Если есть тревога, нажатие сначала отключает её звук, а не обязательно закрывает клапан. Смотрите текущее состояние. Для явного управления используйте меню клапана или веб-интерфейс.</p></div>
<h2>Меню устройства</h2><p>«Выбрать этап», «Задать/снять опору» для выделенного датчика, контекстное действие клапана, «Автоматика этапа», «Сброс тревоги», «Работа на себя», «Новый сеанс», «Выбрать процесс», «Весы», поворот экрана. Смена этапа/процесса и действия, способные открыть клапан, запрашивают подтверждение.</p>
<h2>Повернуть изображение на 180°</h2><ol class="steps"><li>Нажмите энкодер и прокрутите меню до «ЭКРАН: 0 → 180».</li><li>Нажмите энкодер ещё раз. Поворот применяется сразу и сохраняется.</li><li>Для возврата выберите «ЭКРАН: 180 → 0».</li></ol>
<h2>Меню весов</h2><p>Позволяет включить/выключить весы, обнулить, задать или сбросить цель, ввести крепость и температуру жидкости, выполнить калибровку известной массой и подтвердить достижение цели. Нажатие сохраняет число, отдельная кнопка отменяет ввод. Полная процедура — в разделе <a href="#scales">«Весы»</a>.</p>
<p>Развёрнутые допуски каналов, состав этапов, шаблоны, Wi-Fi и индивидуальные поправки удобнее задавать в браузере. Экран не является сенсорным.</p>
""", "энкодер кнопка экран 180 поворот меню без телефона"),

chapter("sensors", "Температуры", "Датчики: входы, названия и роли",
"Физический вход, назначение в процессе и адрес самого датчика — разные сущности.", r"""
<h2>Подключение и обнаружение</h2><p>У прибора четыре независимых входа DS18B20. На один вход подключается один датчик. ROM-адрес определяется автоматически; выбирать датчик вручную из списка не нужно. Два датчика на одном входе считаются ошибкой. Переставляйте и подключайте зонды при выключенном питании.</p>
<h2>Настроить канал</h2><ol class="steps"><li>Откройте карточку нужного датчика → «Управление и параметры».</li><li>Укажите понятное «Название блока», например «Пар в колонне» или «Вода на выходе».</li><li>Выберите логическую роль: пар в колонне, жидкость отбора, куб, охлаждающая вода, дефлегматор, другая точка либо «Не задана».</li><li>Если этот канал должен управлять клапаном, отметьте «Управляет клапаном 1». Прежняя привязка с другого канала снимается.</li><li>Задайте допуски, задержку, гистерезис и восстановление. Нажмите «Сохранить параметры» и проверьте фактические значения.</li></ol>
<h2>Как работают роли</h2><p>Роль помогает применить шаблон к датчику нужного узла независимо от номера разъёма. Роль «Пар в колонне» сама не включает управление клапаном: для этого нужна отдельная отметка. Если требуемая роль отсутствует или назначена неоднозначно, исправьте назначения до выбора шаблона.</p>
<h2>Сколько каналов показывать</h2><p>На странице «Настройки» выберите количество датчиков от 1 до 4 и сохраните. Используются первые выбранные физические входы. Это не удаляет произвольный средний канал. Не скрывайте управляющий вход, рассчитывая продолжать прежнюю автоматику.</p>
<h2>Замена и перестановка</h2><p>При замене прошивка принимает ROM нового датчика, сбрасывает его текущий контроль и опорную. Название, роль и параметры относятся к физическому входу. <a href="#calibration">Поправка</a>, напротив, привязана к ROM и переносится вместе с датчиком. После перестановки проверьте все три вещи: название/роль входа, ROM и отображаемую температуру.</p>
<p>Кнопки «Повторно проверить входы» в карточке или «Проверить входы» в настройках запускают обнаружение. Назначенный ранее, но пропавший датчик даёт ошибку; никогда не назначенный вход обозначается отдельно как неназначенный.</p>
""", "DS18B20 ROM адрес разъем вход название роль заменить переставить число датчиков"),

chapter("temperature", "Температуры", "Опорная температура и рабочее окно",
"Настройте, какое отклонение допустимо и сколько ждать подтверждения и восстановления.", r"""
<h2>Включить контроль</h2><ol class="steps"><li>Проверьте название и исправность нужного датчика. Дождитесь достаточного числа корректных измерений.</li><li>Дождитесь нужного рабочего состояния и нажмите «Зафиксировать температуру» — текущая температура станет опорной.</li><li>Либо введите «Опорная вручную, °C» и нажмите «Установить опорную».</li><li>Проверьте «Опорная», «Отклонение» и «Рабочее окно». Не ограничивайтесь цветом статуса.</li></ol>
<h2>Параметры канала</h2><div class="table-wrap"><table><thead><tr><th>Поле</th><th>Диапазон интерфейса</th><th>Что означает</th></tr></thead><tbody><tr><td>Допуск вниз / вверх</td><td>0,05…10 °C каждый</td><td>Нижняя граница = опорная − допуск вниз; верхняя = опорная + допуск вверх.</td></tr><tr><td>Задержка тревоги</td><td>0…300 с</td><td>Время устойчивого выхода до температурной тревоги. Дополнительно нужны последовательные подтверждения.</td></tr><tr><td>Гистерезис</td><td>0…5 °C</td><td>Насколько глубже внутрь окна должна вернуться температура для начала восстановления.</td></tr><tr><td>Возврат в норму</td><td>0…600 с</td><td>Непрерывная выдержка после возврата. Повторный выход прерывает её.</td></tr><tr><td>Опорная вручную</td><td>−55…125 °C</td><td>Рабочая точка контроля, а не команда нагревателю.</td></tr></tbody></table></div>
<h2>Пример чтения окна</h2><p>При опорной 77,50 °C и допусках вниз 0,10 / вверх 0,20 границы составят 77,40 и 77,70 °C. Показание на границе или за ней уже считается выходом. После верхнего отклонения при гистерезисе 0,05 °C восстановление начнётся при возврате не выше 77,65 °C, затем должна пройти заданная выдержка. Это пример расчёта, не рекомендация режимов перегонки.</p>
<div class="callout warning"><strong>Задержка тревоги не задерживает закрытие автоматического отбора.</strong><p>На этапе с температурной автоматикой клапан закрывается уже в состоянии «Отклонение» (WARNING), до звуковой тревоги. Не увеличивайте задержку, ожидая удержать клапан открытым.</p></div>
<h2>Изменение на ходу</h2><p>Параметры можно сохранять во время работы. Автоматика оценивает текущее состояние по новым значениям: изменение окна или опорной может остановить либо разрешить отбор. «Снять с контроля» удаляет опорную; на температурно-автоматическом этапе это оставляет клапан закрытым, но не переводит его в ручной режим.</p>
<h2>Отображение</h2><p>В «Настройках» выбираются 1, 2 или 3 знака после запятой. Округление влияет на показ и график, а не на внутренние сравнения. Дополнительные цифры не повышают точность датчика. «Стабильно» — оценка тренда, а не подтверждение абсолютной точности и не автоматическая фиксация опорной.</p>
""", "опора допуск окно задержка гистерезис восстановление зафиксировать контроль WARNING"),

chapter("calibration", "Температуры", "Индивидуальные поправки датчиков",
"Одна сохранённая поправка следует за датчиком при смене разъёма.", r"""
<h2>Что показывается в настройках</h2><p>На странице «Настройки» → «Корректировка датчиков» для каждого входа видны ROM-адрес, исходное чтение, поправка и итоговая температура. Итоговая температура отображается после поправки и сглаживания, поэтому при быстром изменении не обязана точно совпадать с мгновенной суммой двух полей.</p>
<h2>Внести поправку</h2><ol class="steps"><li>Поместите сравниваемые зонды и проверенный ориентир в одинаковые устойчивые условия. Дождитесь выравнивания, не сравнивайте переходные показания.</li><li>Проверьте ROM нужного датчика и его исходную температуру.</li><li>Рассчитайте <strong>поправку = температура ориентира − исходное показание</strong>. Например: 50,00 − 50,30 = −0,30 °C.</li><li>Введите значение от −5 до +5 °C и нажмите «Сохранить поправку» именно у этого датчика.</li><li>Проверьте подтверждение и итоговое показание после стабилизации. Изменение с ROM попадает в журнал.</li></ol>
<h2>Сохранение и замена</h2><ul><li>Поправки хранятся отдельно от настроек входов в постоянной памяти.</li><li>Знакомый ROM получает свою поправку в любом разъёме.</li><li>Новый неизвестный ROM получает 0; запись старого датчика не исчезает при его замене.</li><li>Сохранение 0 снимает индивидуальную поправку этого ROM.</li><li>Сброс до заводских настроек очищает таблицу поправок.</li></ul>
<h2>Что поправка не исправляет</h2><p>Обрыв, конфликт датчиков, ошибка CRC адреса, некорректное число и показание вне допустимого диапазона проверяются до применения поправки. Калибровка не превращает неисправное чтение в исправное. Один постоянный сдвиг не устраняет нелинейность, дрейф, шум или тепловую инерцию.</p>
<div class="callout"><strong>Согласованность — не абсолютная точность.</strong><p>Выравнивание нескольких датчиков по среднему сближает их показания, но не доказывает истинную температуру. Бытовой щуп сам по себе не эталон; кипящая вода без учёта условий тоже не гарантирует ровно 100 °C. Проверяйте поправку в области рабочих температур, особенно для куба.</p></div>
""", "калибровка поправка ROM исходная итоговая минус плюс эталон"),
chapter("templates", "Процесс и отбор", "Процессы и сохранённые шаблоны",
"Как не перепутать правку редактора, сохранение шаблона и применение к прибору.", r"""
<h2>Доступные шаблоны</h2><p>Есть четыре общих слота — «Наблюдение», «Первый перегон», «Отбор по жидкости», «Контроль по пару» — и три пользовательских. Сохранённые слоты можно редактировать. Поэтому их содержимое на вашем приборе может отличаться от заводского.</p>
<h2>Выбрать процесс для работы</h2><ol class="steps"><li>На главной странице в поле «Текущий процесс» выберите сохранённый шаблон.</li><li>Прочитайте подтверждение: прибор скопирует его в текущий процесс, начнёт с первого этапа и применит его режим клапана.</li><li>Подтвердите и проверьте название этапа, назначение управляющего датчика и состояние клапана.</li></ol>
<div class="callout warning"><strong>Выбор процесса может изменить выход клапана.</strong><p>Опорные температуры и допуски каналов не подменяются шаблоном. Сначала проверьте роли датчиков и режим первого этапа. Шаблон с первым этапом «Всегда открыт» может разрешить отбор.</p></div>
<h2>Изменить и сохранить шаблон</h2><ol class="steps"><li>Откройте «Настройка температурных этапов и шаблонов» — страницу <code>/process</code>.</li><li>Выберите слот и нажмите «Загрузить в редактор». Это ещё не меняет рабочий процесс.</li><li>Измените этапы, переходы, клапан и ШИМ.</li><li>Нажмите «Сохранить как шаблон» и подтвердите перезапись выбранного слота.</li><li>Для работы с ним отдельно выберите сохранённый шаблон на главной странице.</li></ol>
<h2>Сохранить текущий процесс</h2><p>Кнопка «Сохранить как текущий процесс» применяет содержимое редактора к текущей работе, а не перезаписывает выбранный слот шаблона. Если редактируете во время работы, проверьте сохранённый текущий этап и выход. Сохранение этапов перезапускает цикл ШИМ и сбрасывает накопленное снижение.</p>
<h2>Вернуть заводской шаблон</h2><p>«Вернуть заводской шаблон» восстанавливает выбранный сохранённый слот после подтверждения. Это не полный сброс прибора. Текущий процесс отдельно не заменяется этим действием. Если нужно начать работу с восстановленным вариантом, примените его на главной странице.</p>
<p>Надпись «Изменён вручную» в быстром выборе означает, что текущие этапы не совпадают с сохранённым шаблоном. Это не ошибка.</p>
""", "шаблон сохранить загрузить применить заводской пользовательский процесс"),

chapter("stages", "Процесс и отбор", "Настройка температурных этапов",
"Последовательность до десяти этапов с независимыми переходами и режимами клапана.", r"""
<h2>Открыть редактор</h2><p>Внизу главной страницы выберите «Настройка температурных этапов и шаблонов». В текущем интерфейсе редактор открывается отдельной страницей <code>/process</code>. Кнопка «Вернуться» ведёт к управлению; несохранённые правки не следует считать применёнными.</p>
<h2>Поля этапа</h2><div class="table-wrap"><table><thead><tr><th>Настройка</th><th>Назначение</th></tr></thead><tbody><tr><td>Название</td><td>До 24 символов. Появляется в управлении и событиях.</td></tr><tr><td>Режим клапана</td><td>Всегда закрыт / всегда открыт / автоматически по температуре.</td></tr><tr><td>Блок датчика</td><td>Источник условия входа в этот этап, не обязательно управляющий канал клапана.</td></tr><tr><td>Переход на этап</td><td>Вручную или по превышению заданной температуры.</td></tr><tr><td>Оповещение об автоматическом переходе</td><td>Отдельный сигнал, если переход выполнила автоматика.</td></tr><tr><td>Работа на себя</td><td>Для соответствующего этапа — ожидание плато и подтверждаемый таймер.</td></tr><tr><td>ШИМ клапана</td><td>Независимые процент, цикл, минимумы и снижение именно этого этапа.</td></tr></tbody></table></div>
<h2>Порядок настройки</h2><ol class="steps"><li>Загрузите нужный шаблон в редактор или работайте с текущими этапами.</li><li>Задайте названия и режим клапана каждого этапа.</li><li>Начиная со второго этапа, выберите ручной либо температурный вход. Для температурного укажите датчик и порог.</li><li>Добавьте этап кнопкой «+ Добавить этап» или удалите ненужный. Допустимо от 1 до 10 этапов; первый всегда начальный.</li><li>Настройте оповещения, таймер и ШИМ по необходимости.</li><li>Сохраните текущий процесс или шаблон нужной кнопкой. Проверьте результат на главной странице.</li></ol>
<h2>Как происходит автоматический переход</h2><p>Проверяется условие только <strong>следующего</strong> этапа. Превышение порога должно подтверждаться примерно 5 секунд при доступном датчике. При охлаждении этап автоматически назад не возвращается. Первый этап не имеет температурного условия входа.</p>
<h2>Перейти вручную</h2><p>Кнопка «Перейти на этап» рядом с текущим состоянием выбирает следующий. В раскрытом блоке «Сеанс … · управление» можно выбрать любой этап через «Произвольный этап» и подтвердить. На экране прибора используется меню «Выбрать этап». После выбора применяется режим клапана этапа.</p>
<div class="callout"><strong>Порог перехода и опорная — не одно и то же.</strong><p>Порог меняет этап. Опорная и допуски контролируют канал. Они могут относиться к разным датчикам и настраиваются в разных местах.</p></div>
""", "этапы порог переход датчик ручной автоматический 5 секунд десять"),

chapter("self-reflux", "Процесс и отбор", "Работа на себя и температурное плато",
"Как запустить отсчёт только после стабилизации и подтверждения закрытого отбора.", r"""
<h2>Подготовить этап</h2><ol class="steps"><li>В редакторе этапов включите «Работа на себя» для соответствующего этапа.</li><li>Выберите датчик, по которому оценивается плато, и длительность от 1 до 180 минут.</li><li>Проверьте режим клапана: для работы без отбора обычно нужен «Всегда закрыт». Сохраните процесс/шаблон.</li><li>Перейдите на этот этап и убедитесь физически, что отбор закрыт.</li></ol>
<h2>Состояния таймера</h2><dl class="definitions"><div><dt>Ожидание стабильного плато</dt><dd>Датчик ещё не дал нужного устойчивого участка. Не компенсируйте нестабильность ложной опорной.</dd></div><div><dt>Плато стабильно</dt><dd>Появляется предложение подтвердить закрытый отбор и начать отсчёт.</dd></div><div><dt>Работа на себя</dt><dd>Отображается оставшееся время. Процедура привязана к текущему этапу и данным выбранного датчика.</dd></div><div><dt>Работа на себя завершена</dt><dd>Доступна кнопка перехода к следующему этапу. Сам факт окончания таймера не означает физического открытия клапана.</dd></div></dl>
<h2>Запустить и закончить</h2><p>Нажмите «Начать работу на себя» в блоке процесса и подтвердите. После завершения прочитайте предложение перехода и подтвердите его отдельно. На локальном экране аналогичное действие доступно через «Работа на себя».</p>
<h2>Если таймер не запускается</h2><p>Проверьте выбранный этап, включённую функцию, нужный датчик и его связь. «Стабильно» — оценка температурного участка, а не измерение состава продукта. Если вы сменили этап/процесс/сеанс, не рассчитывайте на продолжение прежнего незавершённого таймера.</p>
<div class="callout"><strong>Таймер не заменяет решение оператора.</strong><p>Длительность и критерии готовности определяются вашей установкой и технологией. Заводское значение — отправная настройка интерфейса, не универсальная рекомендация.</p></div>
""", "плато стабильно работа на себя таймер 20 минут головы"),

chapter("sessions", "Процесс и отбор", "Сеансы и новый запуск",
"Как отделить одну работу от другой, не стирая историю.", r"""
<h2>Начать новый сеанс вручную</h2><ol class="steps"><li>На главной странице раскройте «Сеанс … · управление».</li><li>Нажмите «Начать новый сеанс».</li><li>В подтверждении проверьте номер и первый этап.</li><li>После подтверждения убедитесь, что выбран первый этап текущего процесса и ожидаемый режим клапана.</li></ol>
<p>Прибор начинает новую группу записей, возвращает текущий процесс на первый этап, сбрасывает незавершённую работу на себя и накопленное снижение ШИМ. Опорные температуры и существующие тревоги не очищаются только из-за нового сеанса. Старые данные остаются до циклической перезаписи.</p>
<div class="callout warning"><strong>Проверьте первый этап.</strong><p>Новый сеанс применяет его режим клапана. Если в собственном процессе первый этап разрешает открытие, начало сеанса тоже может его разрешить.</p></div>
<h2>Предложение при нагреве</h2><p>После устойчивого роста температуры прибор может предложить новый сеанс. Предпочтение отдаётся датчику куба, затем пара в колонне, затем доступному каналу. Самостоятельного начала сеанса из такого предложения нет: решение подтверждает оператор.</p>
<h2>После выключения и перезагрузки</h2><p>При загрузке создаётся новый номер сеанса, чтобы относительные времена разных запусков не смешивались. Сохранённые журналы восстанавливаются; опорные температуры и активная цель весов не восстанавливаются как действующие команды. Клапан закрыт до явного действия.</p>
<h2>Сеанс и смена ёмкости</h2><p>Замена банки не требует нового сеанса сама по себе. Обнулите весы с новой тарой и отдельно проверьте цель. В отчёте сброс массы учитывается как ограничение расчёта; сумма по нескольким ёмкостям не должна восприниматься как автоматически посчитанный общий выход.</p>
""", "сеанс новый запуск предложение нагрев перезагрузка история"),

chapter("valve", "Процесс и отбор", "Клапан: ручной режим и автоматика",
"Три команды оператора и три политики этапа — это два разных уровня управления.", r"""
<h2>Команды в блоке клапана</h2><div class="table-wrap"><table><thead><tr><th>Команда</th><th>Что происходит</th></tr></thead><tbody><tr><td>Открыть вручную</td><td>Непрерывное открытие без тайм-аута. Температура и ШИМ не управляют выходом.</td></tr><tr><td>Закрыть вручную</td><td>Клапан остаётся закрытым, автоматика приостановлена до явного возврата.</td></tr><tr><td>Автоматика этапа</td><td>Управление передаётся текущему этапу. Он может сразу разрешить открытие.</td></tr></tbody></table></div>
<h2>Политики внутри этапа</h2><ul><li><strong>Всегда закрыт:</strong> автоматический отбор запрещён.</li><li><strong>Всегда открыт:</strong> отбор разрешён без температурного контроля; если включена ШИМ, разрешены её импульсы.</li><li><strong>Автоматически по температуре:</strong> нужен один выбранный управляющий датчик, достоверные чтения, опорная и состояние «Норма».</li></ul>
<h2>Настроить температурную автоматику</h2><ol class="steps"><li>В карточке нужного канала отметьте «Управляет клапаном 1» и сохраните.</li><li>Настройте опорную, допуски и восстановление этого канала.</li><li>У текущего этапа задайте режим «Автоматически по температуре» и сохраните процесс.</li><li>Верните «Автоматику этапа» в блоке клапана и подтвердите.</li><li>Проверьте причину состояния и фактическую работу на холодной установке.</li></ol>
<h2>Остановка и восстановление</h2><p>Выход за рабочее окно закрывает клапан уже при «Отклонении». Возврат с учётом гистерезиса запускает выдержку. После непрерывного восстановления до «Нормы» отбор снова разрешается. При сомнительном чтении управляющего канала выход закрывается, не дожидаясь окончательного подтверждения отказа. Возврат требует нескольких последовательных корректных чтений и предусмотренного восстановления, а не одного удачного контакта.</p>
<p>Ошибка другого датчика записывается и сигнализируется, но не должна подменять независимый управляющий канал. Снятие его опорной, напротив, закрывает температурно-автоматический отбор. В ручном открытии этих температурных ограничений нет.</p>
<h2>Настройки во время работы</h2><p>Параметры можно менять без обязательного ручного закрытия. Оценка выполняется по новым значениям, поэтому результат может сразу измениться. После ручного открытия/закрытия верните управление кнопкой «Автоматика этапа», иначе изменение температуры не возобновит управление.</p>
<div class="callout warning"><strong>Индикация — не датчик положения.</strong><p>Прибор показывает электрическую команду. Заклинивший или неправильно подключённый клапан не становится исправным от надписи «Закрыт».</p></div>
""", "клапан автоматика открытие закрытие manual AUTO_READY PAUSED FAULT GPIO14"),

chapter("pwm", "Процесс и отбор", "ШИМ: импульсный отбор",
"Процент задаёт долю времени полного открытия клапана, а не его промежуточное положение.", r"""
<h2>Когда использовать</h2><p>Прибор чередует полное открытие и закрытие обычного клапана. Это низкочастотный импульсный режим, не регулировка тока катушки и не сервопривод игольчатого крана. Настройка независима для каждого этапа.</p>
<h2>Включить на выбранном этапе</h2><ol class="steps"><li>Откройте редактор этапов и раскройте у нужного этапа «ШИМ клапана».</li><li>Отметьте «Включить работу по ШИМ».</li><li>Укажите «Открытие, %» от 0 до 100.</li><li>Выберите автоматический расчёт периода или ручной. При ручном введите период от 1 до 3600 с.</li><li>Задайте минимальное время открытия и закрытия от 1 до 60 с каждое.</li><li>Проверьте строку «Расчёт»: период и фактические времена. Сохраните текущий процесс либо шаблон.</li></ol>
<h2>Как рассчитывается цикл</h2><p>Для доли <code>d = процент / 100</code> период равен максимуму из выбранного периода (в автоматике — 10 с), <code>минимум открытия / d</code> и <code>минимум закрытия / (1 − d)</code>. Даже ручной период увеличивается, если иначе нельзя соблюсти минимумы. Времена округляются до миллисекунд.</p>
<div class="table-wrap"><table><thead><tr><th>Процент</th><th>Открыт</th><th>Закрыт</th><th>Цикл</th></tr></thead><tbody><tr><td>5%</td><td>1 с</td><td>19 с</td><td>20 с</td></tr><tr><td>10%</td><td>1 с</td><td>9 с</td><td>10 с</td></tr><tr><td>50%</td><td>5 с</td><td>5 с</td><td>10 с</td></tr><tr><td>50%, ручной период 20 с</td><td>10 с</td><td>10 с</td><td>20 с</td></tr><tr><td>0% / 100%</td><td colspan="3">Постоянно закрыт / непрерывно открыт при разрешении этапа.</td></tr></tbody></table></div><p>Примеры рассчитаны с минимумами по 1 с. Непредставимый цикл больше часа останавливает отбор, а не увеличивает процент.</p>
<h2>Как читать текущий ШИМ</h2><p>Под названием этапа на главной странице при включённой ШИМ показаны текущий процент, заданный при отличии, открытие/закрытие/цикл, число снижений и состояние. «Пауза цикла» — штатное закрытие, не температурная остановка. В ручном режиме написано, что ШИМ не действует. На TFT текущий процент обозначается «Ш…%».</p>
<div class="callout"><strong>Процент не гарантирует расход.</strong><p>Если полностью открытый отбор даёт 1000 мл/ч, 10% — лишь приближение к 100 мл/ч. Переходные процессы, давление, дренаж трубок и механика могут изменить результат. Проверьте реальный расход на воде и по весам. Качество продукта процентом не гарантируется.</p></div>
""", "ШИМ PWM процент цикл импульс 5 10 50 открытие закрытие период"),

chapter("reduction", "Процесс и отбор", "Снижение ШИМ после температурной остановки",
"Включение снижения, его тип и величина задаются отдельно от самого ШИМ.", r"""
<h2>Параметры</h2><ol class="steps"><li>В блоке ШИМ этапа выберите «Снижение после остановки: Да». «Нет» сохраняет процент после остановок.</li><li>Выберите тип: «Абсолютный» или «Относительный».</li><li>Введите величину снижения и нижнюю границу открытия.</li><li>Проверьте пример следующего процента в расчёте и сохраните.</li></ol>
<div class="table-wrap"><table><thead><tr><th>Тип</th><th>Из 50 при величине 10</th><th>Повторное снижение</th></tr></thead><tbody><tr><td>Абсолютный</td><td>50% − 10 процентных пунктов = 40%</td><td>Затем 30%, 20%… до нижней границы.</td></tr><tr><td>Относительный</td><td>50% × 0,90 = 45%</td><td>Затем 40,5%, 36,45%… до нижней границы.</td></tr></tbody></table></div>
<h2>Что считается остановкой</h2><p>Процент уменьшается один раз за эпизод температурного ограничения управляющего датчика после предшествующей разрешённой работы. Повторный выход во время незавершённого восстановления не вызывает ещё одно снижение. Штатная закрытая часть цикла, ручной режим и ошибка чтения датчика сами по себе процент не уменьшают.</p>
<p>После полного восстановления начинается новый цикл с уменьшенным процентом. Пересчитывается и длительность цикла: например, при малом проценте он может увеличиться, чтобы оставить открытие не короче минимума. При достижении нуля отбор прекращается, этап автоматически не меняется.</p>
<h2>Когда накопленное снижение сбрасывается</h2><p>При смене этапа, начале нового сеанса, выборе/сохранении процесса или изменении его параметров. Уменьшенный во время работы процент не записывается в NVS на каждом цикле. После перезагрузки проверьте базовые установки и вручную разрешите автоматику.</p>
<h2>Пресеты редактора</h2><ul><li><strong>Головы:</strong> 10%, автоматический цикл, минимумы по 1 с, снижение выключено, нижняя граница 0%, температурная автоматика.</li><li><strong>Тело:</strong> 50%, автоматический цикл, минимумы по 1 с, относительное снижение 10%, нижняя граница 5%, температурная автоматика.</li></ul><p>Кнопки пресетов заполняют редактор и ничего не применяют до сохранения. Для температурной автоматики нужны управляющий датчик и опорная. В существующих и перенесённых старых этапах ШИМ не включается автоматически.</p>
""", "снижение абсолютный относительный процентные пункты пресет головы тело нижняя граница"),

chapter("workflow-monitor", "Практические сценарии", "Наблюдение без автоматического отбора",
"Самый простой сценарий для знакомства с датчиками, графиком и журналом.", r"""
<ol class="steps"><li>Проверьте количество датчиков, их названия и роли.</li><li>Выберите сохранённый процесс «Наблюдение». Проверьте его содержимое, если раньше редактировали слот.</li><li>Оставьте клапан закрытым вручную либо убедитесь, что текущий этап не разрешает его открытие.</li><li>При необходимости задайте опорные и допуски для температурных уведомлений.</li><li>Наблюдайте температуры и график; в конце выгрузите события и показания.</li></ol>
<h2>Что будет работать</h2><p>Температуры, стабильность, контроль отклонений, оповещения, журнал, история, калькулятор и подключённые весы доступны независимо от необходимости управлять отбором. Можно контролировать несколько температур, но только одна привязка канала предназначена для клапана.</p>
<h2>Чего не произойдёт</h2><p>Само название «Наблюдение» не отключает нагрев и не гарантирует сохранность изменённого пользователем шаблона. Проверяйте фактическую политику этапа и состояние выхода. После потери Wi-Fi наблюдение на приборе продолжается; в браузере старые данные помечаются как потерявшие связь.</p>
""", "наблюдение контроль без клапана проверка первый раз"),

chapter("workflow-first-run", "Практические сценарии", "Первый перегон",
"Как использовать последовательность этапов, не принимая пороги за универсальный рецепт.", r"""
<ol class="steps"><li>Назначьте роль «Куб» соответствующему датчику. Остальные роли задайте по фактическому размещению.</li><li>Откройте редактор и загрузите «Первый перегон». Просмотрите этапы и пороги на своём приборе.</li><li>Для заводского варианта последовательность включает нагрев, подготовку охлаждения, отбор сырца и завершение. Температурные входы в этапы относятся к кубу; промежуточный переход может быть ручным.</li><li>Задайте пороги и оповещения по своей установке, сохраните шаблон и примените его.</li><li>Проверьте политику клапана: первый перегон сам по названию не включает автоматический отбор.</li><li>Начните отдельный сеанс. Нагрев, охлаждение и технологические решения выполняйте самостоятельно.</li><li>Подтверждайте уведомления о переходах, наблюдайте график и завершите работу по инструкции аппарата. Затем экспортируйте журналы.</li></ol>
<h2>Важное ограничение</h2><p>Значения порогов, находящиеся в заводском шаблоне или записи испытания, иллюстрируют настройки, а не готовую технологию для любой загрузки. Температура не запускает охлаждение и не отключает нагрев. Переход к «Завершению» меняет этап и его режим клапана, но не обесточивает аппарат.</p>
<h2>С весами</h2><p>Можно наблюдать массу и примерный объём. Если крепость отбираемой жидкости изменяется, один постоянный ввод крепости не обеспечивает точный накопленный объём. Считайте измеренной величиной массу, а объём — расчётом по введённым свойствам.</p>
""", "первый перегон сырец нагрев охлаждение куб завершение"),

chapter("workflow-liquid", "Практические сценарии", "Отбор по жидкости: головы и тело",
"Проверенная последовательность настройки интерфейса перед применением автоматики.", r"""
<ol class="steps"><li>Назначьте роли датчикам колонны, куба, воды и отбора. Отметьте один управляющий канал клапана.</li><li>Загрузите шаблон «Отбор по жидкости» в редактор. Проверьте нагрев → работу на себя → головы → тело → завершение.</li><li>Убедитесь, что нагрев и работа на себя не разрешают отбор. Настройте таймер работы на себя.</li><li>На головах выберите непрерывный отбор или включите ШИМ с нужным процентом. Не путайте «Всегда открыт» с температурной автоматикой.</li><li>На теле выберите «Автоматически по температуре». При необходимости настройте ШИМ и отдельное снижение после остановок.</li><li>Сохраните и примените шаблон. Начните новый сеанс. Проверьте первый этап и закрытый выход.</li><li>Дождитесь предусмотренного технологией состояния. Зафиксируйте подходящую опорную и проверьте рабочее окно управляющего датчика.</li><li>Подтвердите начало/окончание работы на себя и ручные переходы. Перед началом отбора проверьте текущий этап и передайте клапан «Автоматике этапа».</li><li>Следите за температурой, состоянием клапана и действующим процентом. После температурной остановки прибор выдержит восстановление и может возобновить отбор.</li><li>При окончании закройте отбор/выберите закрывающий этап и самостоятельно выполните завершение работы установки.</li></ol>
<h2>Если используете фиксированное положение игольчатого крана</h2><p>Сначала измерьте реальный непрерывный расход при этом положении, затем оцените импульсный расход по весам. Умножение на процент — приближение, а не калибровка. Длительность и реакция конкретного клапана должны подходить для выбранных импульсов.</p>
<div class="callout warning"><strong>Цель весов не останавливает отбор.</strong><p>При достижении цели нужно отреагировать на оповещение и самому закрыть клапан или перейти на соответствующий этап.</p></div>
""", "по жидкости головы тело ректификация стартстоп последовательность"),

chapter("workflow-vapor", "Практические сценарии", "Контроль по пару",
"Использование температурного контроля и этапов без несуществующего привода парового крана.", r"""
<ol class="steps"><li>Назначьте датчикам роли по реальным точкам установки, особенно каналу пара в колонне.</li><li>Выберите или загрузите в редактор шаблон «Контроль по пару» и проверьте его этапы.</li><li>Задайте опорные, допуски, восстановление и уведомления каналов.</li><li>Проверьте режим каждого этапа. В заводском паровом шаблоне выход клапана закрыт.</li><li>Запустите отдельный сеанс, наблюдайте температуры, фиксируйте переходы вручную либо используйте настроенные температурные условия.</li><li>После работы выгрузите журнал и соберите отчёт.</li></ol>
<h2>Назначение этого режима</h2><p>Шаблон организует контроль и регистрацию процесса. Он не добавляет в прибор привод парового отбора, моторизацию игольчатого крана, регулировку воды или нагрева. Если вручную меняете политику выхода, это по-прежнему управление тем же подключённым клапаном, а не управление аппаратом целиком.</p>
<h2>Почему может быть тревога при закрытом выходе</h2><p>Контроль температуры существует отдельно от разрешения отбора. Канал может сообщать отклонение, даже если этап всё время держит клапан закрытым. Разбирайте причину по названию канала и журналу, а не только по индикатору клапана.</p>
""", "контроль по пару паровой отбор режим пар кран"),

chapter("preflight", "Начало работы", "Помощник и предпусковая проверка",
"Проверка готовности до начала процесса, без открытия клапана из помощника.", r"""
<h2>Подготовка нового процесса</h2><ol class="steps"><li>Внизу главной страницы прибора откройте «Подготовка и проверка» — страницу <code>/assistant</code>.</li><li>На вкладке «Настройка» выберите сохранённый шаблон. Проверьте список этапов и необходимые роли датчиков.</li><li>Если нужно применить этот шаблон, сначала закройте клапан. Нажмите «Применить шаблон» и подтвердите: процесс вернётся на первый этап, но новый сеанс сам не начнётся.</li><li>Перейдите к шагу «Датчики». Проверьте вход, название, роль и достоверность температуры. Для изменения параметров вернитесь к карточкам каналов на главной.</li><li>Откройте предпусковую проверку. Убедитесь, что программные проверки не сообщают о проблемах.</li></ol>
<p>Помощник не применяет шаблон, если его первый этап предусматривает открытие выхода. Для такого процесса используйте основное управление и сначала проверьте действие первого этапа. Сама проверка не выдаёт разрешение на отбор.</p>
<h2>Что нужно подтвердить руками</h2><ul><li><strong>Зуммер:</strong> нажмите «Подать тестовый сигнал», убедитесь, что слышите его, и отметьте соответствующий пункт.</li><li><strong>Питание и соединения:</strong> осмотрите их. Входное напряжение аппаратно не измеряется, поэтому зелёная программная проверка не подтверждает исправность блока питания.</li><li><strong>Клапан и трубки:</strong> проверьте физически. Индикация выхода не является датчиком положения клапана или расхода жидкости.</li></ul>
<div class="callout"><strong>Чек-лист — помощь оператору.</strong><p>Отметки не включают автоматику и не заменяют фактическую проверку. После переноса прибора, замены датчика или клапана повторите её.</p></div>
<h2>Остальные вкладки</h2><p>Вкладка «История» открывает <a href="#history">измерения и их экспорт</a>, вкладка «Отчёт» — <a href="#report">построение отчёта по сеансу</a>. Переход на отчёт не запускает его сбор автоматически.</p>
""", "помощник подготовка готовность чек-лист предпусковая проверка тест зуммера"),

chapter("scales", "Весы и расчёты", "Весы: подключение, калибровка и тара",
"Как получить массу жидкости, а не массу ёмкости и случайный ноль.", r"""
<figure class="wide-photo"><a href="assets/scale.jpg" target="_blank" rel="noopener"><img src="assets/scale.jpg" alt="Приёмная колба стоит на подключённых к ПарДозору весах" width="600" height="800" loading="lazy"></a><figcaption>Пример установки приёмной ёмкости на весы. Шланг не должен давить на неё.</figcaption></figure>
<h2>Подготовка</h2><ol class="steps"><li>При выключенном питании подключите совместимый комплект весов к предусмотренному для него разъёму, не к произвольному входу датчика.</li><li>Поставьте весы на ровную устойчивую поверхность. Уберите нагрузку. Проверьте, что площадка не зажата, провод и трубка не создают усилие.</li><li>Откройте «Настройки», включите весы и сохраните. На главной появится блок массы и объёма.</li><li>Дождитесь устойчивого сигнала. При включении и повторном включении весов текущая нагрузка принимается за нулевую: не считайте этот ноль доказательством пустой площадки.</li></ol>
<h2>Калибровка эталонной массой</h2><ol class="steps"><li>В блоке весов раскройте «Параметры жидкости, тара, цель и калибровка», затем «Калибровка эталонной массой».</li><li>Освободите площадку, дождитесь стабильности и выполните обнуление пустых весов.</li><li>Поставьте груз с известной достоверной массой. Введите его массу в граммах и нажмите кнопку калибровки.</li><li>После подтверждения снимите груз и проверьте ноль. Повторно поставьте груз: показание должно быть близко к введённому.</li></ol>
<p>Поле калибровки принимает <strong>50–10 000 г</strong>. Это предел ввода, а не паспортная грузоподъёмность весов: не превышайте допустимую нагрузку вашего комплекта. Коэффициент сохраняется после перезагрузки. Нельзя откалибровать отсутствие сигнала или нестабильную площадку.</p>
<h2>Тарирование перед отбором</h2><ol class="steps"><li>Поставьте пустую приёмную ёмкость и расположите трубку как при работе.</li><li>Дождитесь надписи о стабильном весе.</li><li>Нажмите «Обнулить с ёмкостью». Теперь масса жидкости отсчитывается относительно этой тары.</li><li>После замены банки повторите тарирование. До этого не используйте оставшиеся значения как массу нового отбора.</li></ol>
<p>Снятие ёмкости приостанавливает прогноз. После перезапуска тара и текущая цель не восстанавливаются как готовый рабочий отбор: установите ёмкость и настройте их заново. Выключение весов в настройках также сбрасывает их оперативное состояние.</p>
<h2>Что меняет точность</h2><p>Вибрация, натяжение шланга, касание банки соседними предметами, изменение положения весов, капли на площадке и неверная калибровка. Исправляйте причину механического усилия, а не компенсируйте её новой калибровкой на каждом этапе.</p>
<p>Те же основные действия доступны с экрана в меню «Весы». Для объёма и прогноза дополнительно задайте <a href="#target">параметры жидкости</a>.</p>
""", "весы масса обнулить тара калибровка эталон известный груз нет сигнала"),

chapter("target", "Весы и расчёты", "Объём, скорость отбора и цель",
"Расчёт по массе и плотности: что вводит оператор и что измеряет прибор.", r"""
<h2>Параметры жидкости</h2><ol class="steps"><li>В блоке весов раскройте параметры.</li><li>Введите крепость в процентах объёмной доли <strong>при 20 °C</strong>.</li><li>Введите фактическую температуру жидкости в приёмной ёмкости. Допустимый диапазон модели — −20…+40 °C.</li><li>Нажмите «Применить параметры». Проверьте показанную расчётную плотность.</li></ol>
<p>Начальные значения — 95% об. и 20 °C. Прибор рассчитывает плотность смеси воды и этанола, а затем <strong>объём = масса / плотность</strong>. Крепость не измеряется автоматически. Температура в этом поле вводится отдельно: наличие канала с названием «Отбор» не означает автоматической подстановки его показания.</p>
<div class="callout"><strong>Объём — расчётный.</strong><p>Если крепость меняется по ходу отбора, обновляйте введённое значение. Неверная плотность искажает объём, скорость в мл/ч и время до цели. Для жидкостей с сахаром или заметным экстрактом модель вода–этанол не даёт достоверного результата.</p></div>
<h2>Как задать цель</h2><ol class="steps"><li>Установите и обнулите пустую приёмную ёмкость.</li><li>В поле «Цель, мл» введите 10–10 000 мл и нажмите «Задать цель».</li><li>Следите за текущим объёмом, скоростью и строкой «до цели».</li><li>При достижении цели смените ёмкость или остановите отбор самостоятельно. Кнопка «Подтвердить цель» подтверждает уведомление, но не меняет управление клапаном.</li><li>Для следующей порции задайте новую цель; для отмены используйте «Сбросить цель».</li></ol>
<div class="callout warning"><strong>Достижение цели не закрывает клапан.</strong><p>Это уведомление, а не команда автоматике и не условие перехода этапа. Весы не регулируют ШИМ и не поддерживают заданный расход по обратной связи.</p></div>
<h2>Как читать скорость и прогноз</h2><p>Скорость оценивается по изменению массы во времени. Используется адаптивное окно: быстрый отбор оценивается на более коротком интервале, медленный — на нескольких минутах; для очень слабого потока сбор данных может занимать до примерно девяти минут. Это не мгновенный расходомер.</p>
<ul><li><strong>«—» вместо времени:</strong> ещё недостаточно данных, нет устойчивого прироста массы, снята ёмкость или потерян сигнал.</li><li><strong>Колебания прогноза:</strong> расход действительно меняется, идёт импульсный отбор либо воздействует шланг/вибрация.</li><li><strong>Нулевая скорость:</strong> в используемом интервале не подтверждается положительный отбор. Это не подтверждение механического закрытия клапана.</li></ul>
<p>Изменение свойств жидкости пересчитывает цель по новой плотности и сбрасывает её оповещение. Новая цель также начинает новый эпизод уведомления. После перезагрузки задайте цель заново.</p>
""", "объем объём скорость расход мл/ч цель прогноз плотность крепость банка целевой объем"),

chapter("calculator", "Весы и расчёты", "Калькулятор: все семь инструментов",
"Отдельные расчёты без передачи команд клапану или процессу.", r"""
<h2>Как открыть и сохранить значения</h2><p>Откройте «Калькулятор» внизу главной страницы прибора (<code>/calculator</code>). Выберите задачу и заполните поля. Результат пересчитывается при изменении входных данных; рядом можно нажать «Копировать результат».</p>
<p>Выбранная задача и введённые поля автоматически сохраняются на устройстве после паузы ввода. Перед выходом дождитесь подтверждения сохранения. Значения восстанавливаются после перезапуска и при открытии с другого браузера. «Сбросить поля» очищает черновик калькулятора, но не сбрасывает прибор.</p>
<h2>Какую задачу выбрать</h2><div class="table-wrap"><table><thead><tr><th>Инструмент</th><th>Что ввести</th><th>Что получите</th></tr></thead><tbody>
<tr><td>Разбавить имеющийся продукт</td><td>Исходный объём, исходную и целевую крепость.</td><td>Количество воды и итоговый объём с учётом контракции; простую объёмную оценку для сравнения.</td></tr>
<tr><td>Приготовить заданный объём</td><td>Нужный конечный объём, крепость исходного продукта и конечную крепость.</td><td>Сколько исходного продукта и воды потребуется.</td></tr>
<tr><td>Смешать известные объёмы</td><td>Объём и крепость каждого из двух компонентов.</td><td>Крепость и объём смеси после смешивания.</td></tr>
<tr><td>Подобрать смесь заданной крепости</td><td>Крепости двух компонентов, нужную крепость и конечный объём.</td><td>Объёмы каждого компонента. Цель должна быть строго между двумя исходными крепостями.</td></tr>
<tr><td>Абсолютный спирт</td><td>Объём и крепость жидкости.</td><td>Количество абсолютного спирта.</td></tr>
<tr><td>Фракции и плановый выход</td><td>Объём и крепость загрузки, доли голов и потерь от общего АС, ожидаемую крепость тела.</td><td>Расчётные количества фракций и плановый выход. Начальные нулевые доли — не рекомендация по технологии.</td></tr>
<tr><td>Поправка спиртометра</td><td>Показание спиртометра, градуированного при 20 °C, и температуру пробы.</td><td>Оценку крепости, приведённой к 20 °C.</td></tr>
</tbody></table></div>
<h2>Единицы и ограничения</h2><ul><li>Объёмы в калькуляторе вводятся в <strong>литрах</strong>, цель весов — в миллилитрах. Проверяйте подпись поля.</li><li>Крепость — проценты объёмной доли. Температурная коррекция рассчитана для −20…+40 °C.</li><li>Массово-плотностная модель учитывает уменьшение объёма при смешивании воды и этанола. Сумма исходных объёмов не обязана равняться конечному.</li><li>Модель предназначена для смеси воды и этанола, не для сладких настоек, ликёров и иных многокомпонентных растворов.</li><li>Для проверки спиртометром надёжнее привести пробу к его температуре градуировки.</li></ul>
<p>Калькулятор не измеряет крепость, не задаёт границы фракций, не меняет цель весов и не переводит процесс на этап. Любой перенос результата в настройки выполняет оператор.</p>
""", "калькулятор разбавление смешивание контракция спиртометр абсолютный спирт АС выход фракции сохранить поля"),

chapter("alarms", "Связь и оповещения", "Состояния, тревоги и звуковые сигналы",
"Как отличить отклонение температуры, неисправность датчика и обычное уведомление.", r"""
<h2>Состояния температурного канала</h2><div class="table-wrap"><table><thead><tr><th>Состояние</th><th>Что означает</th><th>Что делать</th></tr></thead><tbody>
<tr><td>Не назначен / UNASSIGNED</td><td>Нет назначенного рабочего датчика.</td><td>Проверить вход и подключение.</td></tr>
<tr><td>Запуск / STARTING</td><td>Собираются первые достоверные показания.</td><td>Дождаться чтения; при затяжном запуске открыть диагностику.</td></tr>
<tr><td>Ожидание фиксации / IDLE</td><td>Температура есть, опорная ещё не задана.</td><td>Для контроля зафиксировать или ввести опорную.</td></tr>
<tr><td>Норма / NORMAL</td><td>Температурный контроль разрешает работу.</td><td>Продолжать наблюдение.</td></tr>
<tr><td>Предупреждение / WARNING</td><td>Показание вышло из рабочего окна, подтверждается тревога.</td><td>Проверить процесс. В температурной автоматике клапан уже закрыт.</td></tr>
<tr><td>Тревога / ALARM</td><td>Температурное отклонение подтверждено.</td><td>Определить канал и устранить причину.</td></tr>
<tr><td>Восстановление / RECOVERING</td><td>Температура вернулась в допустимую область, идёт выдержка.</td><td>Дождаться устойчивого восстановления.</td></tr>
<tr><td>Ошибка датчика / SENSOR_FAULT</td><td>Подтверждены ошибки получения температуры.</td><td>Проверить соединение, провод, датчик и точную причину в журнале.</td></tr>
</tbody></table></div>
<p>Краткая ошибка чтения регистрируется отдельно от подтверждённого отказа. Для управляющего канала сомнительные показания запрещают автоматическое открытие сразу, не дожидаясь громкой тревоги. После ошибок нужны последовательные достоверные чтения; для возвращения из температурной тревоги дополнительно действует настроенная выдержка.</p>
<h2>Что значит «Отключить звук тревоги»</h2><p>Кнопка подтверждает, что оператор увидел событие. Она <strong>не устраняет неисправность, не сбрасывает контроль и не открывает клапан</strong>. Подтверждённая тревога остаётся видимой. Новый эпизод может снова потребовать подтверждения.</p>
<p>У каждого канала есть собственные параметры оповещения. Не путайте их с разрешением автоматике открыть выход: отключение звука не отключает температурное ограничение.</p>
<h2>Звук браузера и зуммер прибора</h2><p>На главной нажмите «Включить звук» — браузеру обычно требуется это действие пользователя. Если вкладка приостановлена, телефон заблокирован или связь потеряна, полагаться на браузерный звук нельзя. Встроенный зуммер работает на самом приборе независимо от открытой вкладки.</p>
<p>У активного зуммера одна высота тона. Типы событий различаются ритмом, а не настоящей мелодией:</p>
<div class="table-wrap"><table><thead><tr><th>Событие</th><th>Ритм</th><th>Приоритет</th></tr></thead><tbody><tr><td>Отказ датчика</td><td>Три коротких сигнала и один длинный; повтор примерно через 2,6 с.</td><td>Самый высокий.</td></tr><tr><td>Температурная тревога</td><td>Два средних сигнала; повтор примерно через 4,2 с.</td><td>Выше уведомлений.</td></tr><tr><td>Достижение объёма</td><td>Средний и короткий сигналы с большой паузой — около 20 с.</td><td>Выше смены этапа.</td></tr><tr><td>Оповещение этапа</td><td>Два коротких сигнала с паузой около 30 с.</td><td>Информационный.</td></tr><tr><td>Проверка зуммера</td><td>Два коротких проверочных сигнала.</td><td>Не перекрывает реальные тревоги.</td></tr></tbody></table></div>
<p>Если активны несколько событий, слышен наиболее приоритетный сигнал. Причину смотрите по состояниям каналов и <a href="#history">журналу</a>, а не пытайтесь определить её только на слух.</p>
""", "тревога авария звук пищалка зуммер мелодии отключить подтверждение ошибка SENSOR_FAULT WARNING ALARM RECOVERING"),

chapter("wifi", "Связь и оповещения", "Wi-Fi: сохранённые сети и подключение",
"До восьми точек доступа с паролями, подключение без перезагрузки и резервная сеть прибора.", r"""
<h2>Первое подключение без роутера</h2><ol class="steps"><li>Когда прибор не подключился к сохранённой сети, найдите на телефоне Wi-Fi <code>ColumnSensor-XXXX</code>.</li><li>Подключитесь с паролем <code>column-setup</code>. Подтвердите, что хотите оставаться в сети без интернета.</li><li>Откройте <a href="http://192.168.4.1/" class="device-link">http://192.168.4.1/</a>. Если телефон отправляет трафик через мобильную сеть/VPN, временно отключите их и повторите.</li><li>Внизу главной страницы откройте «Wi-Fi» (<code>/wifi</code>).</li></ol>
<h2>Добавить домашнюю сеть</h2><ol class="steps"><li>Запустите поиск сетей на странице Wi-Fi. Дождитесь результата и выберите нужную сеть либо введите имя вручную, если сеть скрытая.</li><li>Введите пароль. Прибору нужна сеть <strong>2,4 ГГц</strong>; сеть только 5 ГГц не подходит.</li><li>Выберите действие: сохранить профиль для будущих подключений либо сохранить и подключиться сейчас.</li><li>Дождитесь подтверждения сохранения. При подключении текущая страница может потерять связь — это ожидаемо при смене сети.</li><li>Переведите телефон в ту же домашнюю сеть. Откройте <a href="http://pardozor.local/" class="device-link">http://pardozor.local/</a> либо IP-адрес, показанный на экране прибора.</li></ol>
<h2>Несколько сохранённых сетей</h2><p>Начиная с dev.104 прибор хранит до <strong>8 профилей</strong>. Добавьте, например, домашний роутер и точку доступа телефона. Если сеть при запуске недоступна, прибор ищет другие сохранённые точки; среди видимых известных сетей выбирает подходящую с сильным сигналом. Неудачные подключения временно пропускаются, чтобы не повторять их непрерывно.</p>
<p>Первичная неудачная попытка подключения занимает примерно 15 с; повторная попытка к неудавшейся сети — не немедленно. После устойчивого подключения резервная точка доступа отключается примерно через минуту. Во время стабильного соединения прибор не перескакивает постоянно между сетями ради более сильного сигнала.</p>
<h2>Изменить пароль или удалить профиль</h2><ul><li>У существующего профиля пустое поле пароля означает <strong>оставить сохранённый пароль</strong>, а не стереть его.</li><li>Для действительно открытой сети используйте соответствующий выбор сети без пароля.</li><li>Для смены пароля введите новый и сохраните профиль. Изменение записи текущей сети не означает немедленного переподключения к ней.</li><li>«Подключиться» — отдельное действие. «Удалить» удаляет профиль из памяти; сохраните альтернативную сеть до удаления единственного рабочего профиля.</li><li>Имя сети — до 32 байт; пароль защищённой сети обычно 8–63 байта, либо 64 шестнадцатеричных символа ключа. Длинное имя с кириллицей может занимать больше байт, чем букв.</li></ul>
<h2>Где находятся пароли</h2><p>Профили сохраняются в постоянной памяти прибора и переживают выключение. В интерфейсе сохранённый пароль не раскрывается. Это не означает, что прибор является защищённым хранилищем паролей: используйте доверенную локальную сеть и не открывайте веб-интерфейс напрямую в интернет.</p>
<div class="callout"><strong>Сайт инструкции и страница прибора — разные вещи.</strong><p>Эта инструкция доступна через GitHub Pages. Управление находится на локальном адресе самого прибора. Открытие инструкции не подключает её к ПарДозору, а потеря Wi-Fi не останавливает уже выполняющуюся автоматику.</p></div>
""", "wifi wi-fi вайфай пароль роутер сеть точка доступа подключение сохраненные сети 192.168.4.1 pardozor.local ColumnSensor"),

chapter("history", "Журналы и отчёты", "Журнал событий и история показаний",
"Два разных журнала: причины событий и последовательность измерений.", r"""
<h2>Журнал устройства на главной</h2><p>Внизу главной страницы расположен журнал последних <strong>50 событий</strong> с автоматическим обновлением. В строках видны дата и время, время работы, номер сеанса, уровень, канал/этап и описание.</p>
<ol class="steps"><li>Найдите момент отклонения по времени и сеансу.</li><li>Сопоставьте название канала с кодом события и текстом. Например, ошибка чтения датчика, температурная тревога и переход этапа — разные причины.</li><li>Нажмите «Экспорт журнала» рядом с таблицей. Будет прочитан весь ещё доступный журнал событий, а не только 50 строк на экране.</li><li>Сохраните файл <code>pardozor-events.csv</code>. Если чтение прервалось или журнал изменился во время выгрузки, повторите экспорт.</li></ol>
<p>CSV использует разделитель <code>;</code> и UTF-8. В табличном редакторе при необходимости выберите эти параметры импорта. В выгрузке есть отдельные столбцы кода и сообщения — передавайте их вместе, не только слово «Авария».</p>
<h2>История температур и отбора</h2><p>Откройте «История показаний» внизу главной (<code>/assistant#history</code>). Кнопка «Обновить показания» загружает доступные измерения. Кнопки «Весь журнал CSV» и «Весь журнал JSONL» сохраняют полный доступный журнал измерений: <code>pardozor-measurements.csv</code> и <code>pardozor-measurements.jsonl</code>.</p>
<p>В измерениях присутствуют сеанс и этап, температуры, опорные, отклонения и состояния каналов, а также данные массы/объёма, если они доступны. JSONL — по одному JSON-объекту на строку, удобен для технического разбора. Выгрузка событий и выгрузка измерений дополняют друг друга, но не заменяют одна другую.</p>
<h2>Что сохраняется после выключения</h2><p>Оба журнала сохраняются во Flash и восстанавливаются при следующем запуске. Память кольцевая: при заполнении самые старые записи заменяются новыми.</p>
<div class="table-wrap"><table><thead><tr><th>Журнал</th><th>Вместимость в этой версии</th><th>Когда обновляется Flash</th></tr></thead><tbody><tr><td>Измерения</td><td>43 200 записей — примерно 12 ч при шаге 1 с.</td><td>Пакетами, обычно с интервалом до 10 с.</td></tr><tr><td>События</td><td>2 048 событий; длительность охвата зависит от их количества.</td><td>Пакетами, обычно с интервалом до 2 с.</td></tr></tbody></table></div>
<p>Последние ещё не записанные данные могут потеряться при внезапном отключении питания. Вместимость не означает 12 часов для каждого сеанса отдельно: это общий буфер разных сеансов. При активных ошибках журнал событий заполняется быстрее. Для длительного архива сохраняйте файлы после работы.</p>
<h2>Чтение ошибок</h2><p>В журнале отмечаются ошибки чтения всех активных датчиков, подтверждение отказа, восстановление, замена ROM, изменение поправки, настройки и события процесса. Повторяющиеся одинаковые ошибки могут объединяться/публиковаться периодически со счётчиком — отсутствие отдельной строки на каждую секунду не доказывает отсутствие промежуточных ошибок.</p>
<p>Если дата не определилась, ориентируйтесь на время работы и сеанс; не приписывайте старому запуску сегодняшнюю дату. Подробнее — <a href="#persistence">о времени и памяти</a>.</p>
""", "журнал события история экспорт CSV JSONL память flash кольцевой архив дата ошибка код"),

chapter("report", "Журналы и отчёты", "Отчёт по сеансу",
"Время этапов, отбор и температурные отклонения в одном документе.", r"""
<h2>Как собрать отчёт</h2><ol class="steps"><li>Откройте «Отчёт сеанса» в нижней навигации прибора (<code>/assistant#report</code>).</li><li>Нажмите <strong>«Собрать отчёт»</strong>. Сам переход на вкладку ничего не строит.</li><li>Дождитесь чтения журналов. Не отключайте связь, пока идёт загрузка.</li><li>Выберите нужный номер в поле «Сеанс».</li><li>Просмотрите полноту данных и разделы этапов. Для сохранения нажмите «Печать / PDF» и выберите сохранение в PDF в диалоге браузера.</li></ol>
<h2>Как читать результат</h2><ul><li><strong>Этапы:</strong> последовательность, моменты начала/окончания, относительное время и длительность; календарное время — если оно известно.</li><li><strong>Отбор:</strong> доступные значения массы и объёма по этапам. Это оценка по журналу весов, а не измерение фракционного состава.</li><li><strong>Температуры:</strong> диапазоны, опорные и отклонения по каналам.</li><li><strong>Эпизоды отклонений:</strong> когда начались и закончились, сколько длились. Длительность тревоги канала не обязательно равна времени остановки всего процесса или клапана.</li><li><strong>События:</strong> переходы, ошибки и действия оператора помогают объяснить изменения.</li></ul>
<h2>Ограничения полноты</h2><p>Отчёт формируется из того, что ещё осталось в обоих журналах. Если начало сеанса перезаписано, запись была прервана питанием или выгрузка неполная, итог нельзя считать полным протоколом. Снимайте архив, пока необходимые данные не ушли из кольцевого буфера.</p>
<p>При снятии ёмкости, повторном тарировании или работе без весов непрерывный итог отбора может быть неизвестен. Разность двух показаний по разные стороны тарирования нельзя трактовать как отрицательный отбор. Отчёт не восстанавливает отсутствующие измерения.</p>
<h2>Что передать для разбора проблемы</h2><p>PDF удобен для чтения, но для диагностики приложите также <a href="#history">оба исходных журнала</a> и <a href="#diagnostics">скопированную диагностику</a>. Укажите номер сеанса, этап, примерное время и ожидаемое действие клапана.</p>
""", "отчет отчёт сеанс PDF печать собрать отчет время этапа отклонения отбор протокол"),

chapter("settings", "Настройки и обслуживание", "Общие настройки и сохранение изменений",
"Где меняются параметры и почему у разных блоков собственные кнопки сохранения.", r"""
<h2>Общие настройки</h2><p>Откройте «Настройки» внизу главной страницы (<code>/settings</code>). Это отдельная страница, не всплывающее окно.</p>
<div class="table-wrap"><table><thead><tr><th>Параметр</th><th>Как использовать</th></tr></thead><tbody><tr><td>Знаков после запятой</td><td>1, 2 или 3 знака в температуре. Больше знаков не повышает физическую точность датчика.</td></tr><tr><td>Количество датчиков</td><td>1–4. Активны первые указанное количество физических входов; это не выбор произвольных разъёмов.</td></tr><tr><td>Весы</td><td>Включить или выключить блок весов. Выключение сбрасывает его текущую тару и цель, но не удаляет сохранённый коэффициент калибровки.</td></tr></tbody></table></div>
<ol class="steps"><li>Измените нужные поля.</li><li>Нажмите «Сохранить настройки» и дождитесь сообщения «Настройки применены».</li><li>Нажмите «Вернуться». Одна кнопка возврата без сохранения не применяет черновик.</li></ol>
<h2>Что сохраняется отдельно</h2><ul><li><a href="#calibration">Поправка датчика</a> — кнопкой «Сохранить поправку» в карточке конкретного ROM на той же странице.</li><li><a href="#temperature">Параметры температурного контроля</a> — в раскрываемом блоке соответствующего канала на главной.</li><li><a href="#stages">Этапы и ШИМ</a> — на странице температурных этапов и шаблонов. Сохранение текущего процесса и сохранение шаблона — разные назначения.</li><li><a href="#wifi">Сети и пароли</a> — на странице Wi-Fi.</li><li><a href="#scales">Калибровка весов</a> и <a href="#target">свойства жидкости</a> — в блоке весов.</li><li><a href="#local">Поворот экрана на 180°</a> — через локальное меню прибора.</li><li><a href="#calculator">Черновик калькулятора</a> — автоматически, после паузы ввода.</li></ul>
<h2>После нажатия «Сохранить»</h2><p>Дождитесь именно подтверждения применения. Сообщение о принятой команде или начатой записи ещё не всегда означает завершение сохранения. При ошибке или потере связи вернитесь на страницу, перечитайте фактическое состояние и повторите только нужное действие.</p>
<p>Настройки температуры и клапана можно менять во время работы. Изменение может немедленно изменить разрешение отбора или перезапустить расчёт ШИМ — перед сохранением оцените, что произойдёт с выходом. Фиксация опорной и ручное открытие — рабочие команды, а не параметры, автоматически восстанавливаемые после выключения.</p>
""", "настройки сохранить вернуться точность знаки запятой количество датчиков поворот интерфейс"),

chapter("diagnostics", "Настройки и обслуживание", "Диагностика и помощь с неисправностью",
"Как сохранить техническое состояние и передать данные для разбора.", r"""
<h2>Открыть и скопировать</h2><ol class="steps"><li>В нижней навигации главной страницы нажмите «Диагностика» (<code>/diagnostics</code>).</li><li>Обновите данные и запишите версию прошивки, номер сеанса, время работы и причину последнего запуска.</li><li>Нажмите «Скопировать». Вставьте результат в сообщение или текстовый файл.</li><li>Если браузер не разрешил буфер обмена, используйте предложенное выделение текста или выделите диагностические данные вручную и скопируйте.</li></ol>
<h2>На что смотреть</h2><ul><li><strong>Устройство:</strong> версия, длительность работы, причина перезапуска.</li><li><strong>Память и задачи:</strong> свободная память, состояние внутренних операций и сохранения.</li><li><strong>Датчики:</strong> ROM, состояние и счётчики чтений/ошибок, конкретная последняя причина ошибки.</li><li><strong>Клапан и процесс:</strong> режим управления, текущий этап, запрет/разрешение выхода и ШИМ.</li><li><strong>Журналы:</strong> готовность хранилища, количество и перезапись записей.</li></ul>
<p>Последняя записанная ошибка и накопленный счётчик не означают, что ошибка происходит прямо сейчас. Смотрите также возраст показаний и текущее состояние. Часть рабочих счётчиков относится только к текущему запуску, а журнал содержит и предыдущие.</p>
<h2>Причины ошибок датчиков</h2><div class="table-wrap"><table><thead><tr><th>Техническое обозначение</th><th>Смысл</th></tr></thead><tbody><tr><td><code>PORT_MISSING</code></td><td>Ранее назначенный датчик не обнаружен на входе.</td></tr><tr><td><code>PORT_CONFLICT</code></td><td>На одном входе обнаружено несколько датчиков вместо одного.</td></tr><tr><td><code>ROM_CRC</code></td><td>Не прошла проверка контрольной суммы ROM-адреса.</td></tr><tr><td><code>READ_NO_VALID_VALUE</code></td><td>Не получено допустимое значение от датчика; проверьте соединение и питание.</td></tr><tr><td><code>READ_NONFINITE</code></td><td>Чтение не является конечным числом.</td></tr><tr><td><code>READ_OUT_OF_RANGE</code></td><td>Исходная температура вне −55…+125 °C.</td></tr></tbody></table></div><p>Эти причины уточняют отказ, но не всегда однозначно определяют неисправную деталь: например, недостоверное чтение может быть следствием провода, разъёма или самого зонда. Перепишите обозначение и текст события целиком.</p>
<h2>Минимальный комплект для обращения</h2><ol><li>Диагностика, скопированная во время проблемы, до перезагрузки, если прибор доступен.</li><li>Файлы <code>pardozor-events.csv</code> и <code>pardozor-measurements.jsonl</code> либо CSV показаний.</li><li>Номер сеанса, этап, время, физический вход и ROM подозрительного датчика.</li><li>Что ожидалось и что произошло; режим клапана и изменения настроек перед событием.</li><li>Фото подключения или короткое видео, если симптом механический.</li></ol>
<div class="callout"><strong>Перед публичной отправкой проверьте содержимое.</strong><p>Диагностика может включать имена сети, локальные адреса и идентификаторы датчиков. Не публикуйте пароли и другие личные данные. Для разбора отдельного сбоя не требуется сбрасывать всю память.</p></div>
""", "диагностика скопировать буфер обмена ошибка чтения счетчики память версия помощь неисправность"),

chapter("update", "Настройки и обслуживание", "Обновление прошивки и заводской сброс",
"Плановое обслуживание вне рабочего процесса, с сохранением нужных журналов заранее.", r"""
<h2>Подготовиться к обновлению</h2><ol class="steps"><li>Завершите рабочий процесс. Нагрев и оборудование, не управляемые ПарДозором, отключите их собственными средствами.</li><li>Сохраните нужные журналы и отчёты. Запишите важные настройки, поправки и калибровку: обычная выгрузка журнала не является резервной копией настроек.</li><li>Выберите этап с политикой «Всегда закрыт» и убедитесь, что ручное открытие выключено. Если остаётся ручной режим, верните «Автоматику этапа» именно на этом закрытом этапе.</li><li>Снимите с контроля <strong>все</strong> температурные каналы, убрав их опорные. Убедитесь, что автоматика отключена, выход закрыт и предыдущие сохранения завершены. Одного закрытого импульса ШИМ или ручного закрытия недостаточно для допуска к обновлению.</li><li>Подготовьте файл <code>.bin</code> ПарДозора, предназначенный именно для установленной платы и версии аппаратной части.</li><li>Обеспечьте устойчивые питание и локальную связь. Не обновляйте во время отбора.</li></ol>
<h2>Установить через браузер</h2><ol class="steps"><li>Откройте «Обновление прошивки» (<code>/update</code>).</li><li>Выберите один файл <code>.bin</code> и нажмите «Загрузить прошивку».</li><li>Дождитесь загрузки, проверки и перезапуска. Не выключайте питание, не загружайте второй файл и не запускайте процесс.</li><li>Снова откройте главную страницу. При необходимости переподключитесь к Wi-Fi прибора.</li><li>Проверьте версию внизу страницы, датчики, поправки, процессы, весы и закрытое состояние выхода. Перед новой работой выполните предпусковую проверку.</li></ol>
<p>Перед записью проверяются идентификатор проекта, тип контроллера и целостность образа. Если файл отвергнут, прочитайте точную причину; сообщение о сохранении текущей прошивки не означает установки новой. Старые образы без идентификатора проекта не принимаются.</p>
<p>При сообщении «Сначала снимите все блоки датчиков с контроля» проверьте не только управляющий датчик: опорные должны быть убраны у всех активных каналов. Если идёт сохранение настроек, дождитесь завершения и повторите.</p>
<h2>Заводской сброс — отдельная операция</h2><p>На странице обновления раскройте «Сброс настроек». Кнопка требует обычного подтверждения и ввода слова <strong>СБРОС</strong>. Она удаляет настройки каналов, поправки датчиков, процессы, сохранённые сети Wi-Fi, калибровку весов и другие настройки. Прошивка и журналы процесса во Flash остаются.</p>
<div class="callout warning"><strong>Не используйте сброс как первый шаг диагностики.</strong><p>После него придётся заново настраивать прибор и подключаться к его резервной точке доступа. Сам по себе сброс не устраняет плохой контакт, неисправность датчика или неподходящее питание.</p></div>
<h2>Если прибор не загрузился</h2><p>Не повторяйте перепрошивку наугад и не стирайте Flash целиком. Зафиксируйте, какой файл был установлен и как ведут себя экран/питание. Восстановление через USB-UART выполняют с правильным образом и предварительным сохранением данных, если они доступны. Одновременное питание от внешнего блока и USB для этой платы не следует считать допустимым без отдельной проверки.</p>
""", "прошивка обновление OTA bin USB заводской сброс СБРОС перезагрузка экран не включается"),

chapter("persistence", "Настройки и обслуживание", "Память, дата и поведение после перезапуска",
"Какие данные долговременные, а какие нужно подготовить заново.", r"""
<h2>Что сохраняется</h2><div class="table-wrap"><table><thead><tr><th>Данные</th><th>После выключения</th></tr></thead><tbody><tr><td>Названия, роли и параметры каналов; общие настройки</td><td>Сохраняются после успешной записи.</td></tr><tr><td>Индивидуальные поправки датчиков</td><td>Сохраняются по ROM, независимо от входа.</td></tr><tr><td>Процессы, шаблоны и базовые параметры ШИМ</td><td>Сохраняются; рабочее накопленное снижение ШИМ — нет.</td></tr><tr><td>Сети и пароли Wi-Fi</td><td>Сохраняются, до 8 профилей.</td></tr><tr><td>Коэффициент весов, крепость и температура жидкости</td><td>Сохраняются. Тара, цель и текущий прогноз — оперативные.</td></tr><tr><td>Поворот локального экрана и черновик калькулятора</td><td>Сохраняются после подтверждённой записи.</td></tr><tr><td>Журналы событий и измерений</td><td>Восстанавливаются из кольцевого хранилища, кроме ещё не записанного хвоста.</td></tr><tr><td>Опорные температуры, ручное открытие и разрешение автоматики</td><td>Не восстанавливаются как разрешение продолжить отбор. Выход после запуска закрыт.</td></tr><tr><td>Текущее выполнение этапа и работы на себя</td><td>Не продолжается «с той же секунды». Проверьте первый этап и заново подготовьте запуск.</td></tr></tbody></table></div>
<h2>Откуда берутся время и дата</h2><p>При доступном интернете прибор синхронизирует часы по сети. Если часы ещё не определены, открытый веб-интерфейс может передать время телефона или компьютера. Поэтому на устройстве, с которого вы подключаетесь, должны быть правильные часы.</p>
<p>Календарные отметки сохраняются вместе с данными журнала, когда время известно. После перезагрузки строки предыдущего сеанса не должны получать дату нового запуска. Относительное время работы и номер сеанса позволяют различать запуски даже при отсутствии календарной даты.</p>
<h2>Почему у старой записи может быть «—»</h2><p>Если в момент записи ещё не было достоверного времени или данные пришли из старой версии без календарных отметок, точная дата может быть неизвестна. Последующая синхронизация не даёт права выдумать дату неизвестного прошлого запуска. Чтобы получить полноценный протокол следующей работы, откройте интерфейс с правильными часами и проверьте дату в журнале до начала.</p>
<h2>Как меньше изнашивать Flash</h2><p>Журналы пишутся пакетами и циклически в выделенную область, а не как полная перезапись всех настроек на каждой секунде. Калибровка датчика сохраняется по явной команде, а рабочие импульсы клапана сами не вызывают запись настроек. Ресурс памяти конечен; это не бессрочный архив. Регулярно выгружайте важные данные.</p>
<h2>Проверка после любого перезапуска</h2><ol><li>Сверьте версию, номер сеанса и дату.</li><li>Убедитесь в достоверности всех нужных датчиков и применении их поправок.</li><li>Выберите нужный процесс и этап; проверьте режим выхода и ШИМ.</li><li>Задайте опорные только по фактическому текущему процессу.</li><li>Подготовьте тару и цель весов заново. Затем осознанно разрешите автоматику.</li></ol>
""", "память дата время часы NTP синхронизация перезагрузка сохранение Flash NVS после выключения"),

chapter("troubleshooting", "Справочник", "Если что-то работает не так",
"Проверки по симптому — до сброса настроек и замены деталей.", r"""
<h2>Не открывается веб-интерфейс</h2><ol><li>Проверьте питание и экран самого прибора. Проблема браузера не равна остановке автоматики.</li><li>Подключите телефон к той же сети, что прибор, либо к <code>ColumnSensor-XXXX</code>.</li><li>Используйте IP с экрана; имя <code>pardozor.local</code> поддерживается не во всех сетях. В резервной сети откройте <code>http://192.168.4.1/</code>, именно HTTP.</li><li>Проверьте VPN, изоляцию клиентов роутера и переключение телефона на мобильные данные. Для домашнего подключения нужна сеть 2,4 ГГц.</li><li>Не выполняйте заводской сброс, пока не проверили адрес и подключение.</li></ol>
<h2>Клапан закрыт, хотя температура кажется нормальной</h2><ul><li>Не выбран ли ручной закрытый режим или политика этапа «Закрыт»?</li><li>Есть ли назначенный управляющий канал, достоверный датчик и опорная температура?</li><li>Не идёт ли выдержка восстановления или подтверждение устойчивых чтений после ошибки?</li><li>Не равна ли температура самой границе? Граница рабочего окна считается выходом; округлённое число на экране может скрыть разницу.</li><li>Не идёт ли закрытая часть ШИМ? Какой сейчас фактический процент, не снижен ли он до нуля?</li><li>Не ожидается ли завершение работы на себя? Какова причина в блоке выхода и журнале?</li></ul>
<p>Не открывайте клапан вручную только для обхода непонятной причины. Сначала определите режим, канал и конкретное событие.</p>
<h2>Клапан открыт при тревоге</h2><p>Ручное открытие не подчиняется температурному контролю. Политика этапа «Открыт» также не является температурной автоматикой. Для автоматического закрытия по управляющему каналу нужна именно политика «Автоматически» и включённая автоматика этапа. Тревога другого, не управляющего канала сама по себе не управляет этим выходом.</p>
<h2>Ошибка датчика или неправдоподобная температура</h2><ol><li>Сохраните диагностику и журналы до перезапуска.</li><li>Сверьте ROM, исходную температуру и поправку. Проверьте, что на входе ровно один датчик.</li><li>Остановите процесс перед физическим переподключением. Осмотрите контакт, провод и влагу в разъёме.</li><li>Проверьте, следует ли проблема за самим датчиком при перестановке в другой вход. Не переносите случайный скачок в постоянную поправку.</li><li>Сообщите точный код/причину чтения. Одного числа температуры недостаточно, чтобы отличить сбой контакта от погрешности датчика.</li></ol>
<p>Если завышение возникло после одной загрузки и исчезло после другой, не объявляйте его нормальной калибровочной ошибкой. Сравнивайте исходные чтения, ROM, конфигурацию и журналы разных запусков.</p>
<h2>Нет прогноза весов или цель не остановила отбор</h2><p>Убедитесь, что есть сигнал, ёмкость установлена и тарирована, свойства жидкости верны. При малом расходе подождите накопления тренда. Цель только оповещает: <strong>закрытие клапана по достижении объёма в этой версии не предусмотрено</strong>.</p>
<h2>Изменение настроек не видно</h2><p>Проверьте, в какой блок сохраняли: текущий процесс, отдельный шаблон или карточку канала. Загрузка шаблона в редактор не равна его применению. Дождитесь подтверждения записи, обновите страницу и проверьте фактическое состояние. Очистка кеша браузера не заменяет установку нужной версии прошивки.</p>
<h2>В отчёте нет начала или даты</h2><p>Начало могло быть перезаписано кольцевым журналом; календарное время могло ещё не определиться. Выберите нужный сеанс, проверьте исходные файлы и сообщения о полноте. Сбор отчёта не восстанавливает отсутствующие записи.</p>
<h2>Экран пуст после обновления</h2><p>Проверьте питание, точное имя установленного образа и наличие загрузочного лога. Не стирайте память и не устанавливайте случайные бинарные файлы. Дальнейшие действия — по <a href="#update">восстановлению после обновления</a>, с сохранением данных, если возможно.</p>
""", "не работает проблема нет связи клапан закрыт открыт скачок температура обрыв не видит экран завис ошибка"),

chapter("reference", "Справочник", "Краткая памятка и термины",
"Основные действия и различия, которые важны во время работы.", r"""
<h2>Перед каждым запуском</h2><ol><li>Питание, охлаждение, соединения и физическая работа клапана проверены.</li><li>Датчики достоверны; роли, управляющий канал и поправки соответствуют подключению.</li><li>Выбран нужный процесс, проверены все этапы и политика выхода каждого этапа.</li><li>Опорные, допуски, задержки и восстановление соответствуют текущему процессу.</li><li>Если нужен ШИМ — проверены базовый процент, цикл, минимальные времена и снижение.</li><li>Весы тарированы с пустой ёмкостью; крепость, температура и цель заданы правильно.</li><li>Проверены звук, дата и запись журналов; начат нужный сеанс.</li></ol>
<h2>Главные различия</h2><dl class="definitions"><div><dt>Роль и название</dt><dd>Роль используется логикой шаблонов; название — подпись. Ни то ни другое не заменяет выбор управляющего канала.</dd></div><div><dt>Опорная и поправка</dt><dd>Опорная задаёт центр контроля в текущей работе; поправка исправляет показание конкретного ROM постоянно.</dd></div><div><dt>Процент ШИМ и крепость</dt><dd>Процент ШИМ — доля открытого времени клапана, не процент спирта и не гарантированный расход.</dd></div><div><dt>Снизить на 10 и на 10%</dt><dd>При базовых 50% абсолютное снижение на 10 пунктов даёт 40%, относительное на 10% — 45%.</dd></div><div><dt>Снять звук и устранить тревогу</dt><dd>Подтверждение выключает оповещение, но не исправляет причину и не отменяет запрет отбора.</dd></div><div><dt>Журнал и отчёт</dt><dd>Журнал — исходные записи; отчёт — их представление по выбранному сеансу.</dd></div></dl>
<h2>Если нужно быстро найти действие</h2><div class="table-wrap"><table><thead><tr><th>Действие</th><th>Раздел инструкции</th></tr></thead><tbody><tr><td>Подключиться с телефона</td><td><a href="#wifi">Wi-Fi и адреса</a></td></tr><tr><td>Повернуть экран</td><td><a href="#local">Экран и локальное меню</a></td></tr><tr><td>Настроить контроль температуры</td><td><a href="#temperature">Опорная и рабочее окно</a></td></tr><tr><td>Изменить этап или шаблон</td><td><a href="#stages">Настройка этапов</a></td></tr><tr><td>Настроить головы/тело импульсно</td><td><a href="#pwm">ШИМ</a> и <a href="#reduction">снижение</a></td></tr><tr><td>Объяснить закрытие клапана</td><td><a href="#valve">Режимы выхода</a>, <a href="#troubleshooting">проверки по симптому</a></td></tr><tr><td>Сохранить данные работы</td><td><a href="#history">Экспорт журналов</a> и <a href="#report">отчёт</a></td></tr><tr><td>Передать проблему для разбора</td><td><a href="#diagnostics">Диагностика</a></td></tr></tbody></table></div>
<h2>Как пользоваться этой инструкцией</h2><p>В меню — главы по задачам. Поиск ищет по всему тексту, а не только по заголовкам; можно ввести название кнопки, состояние или код ошибки. Кнопка «Ссылка» копирует адрес текущего раздела. «Печать главы» сохраняет выбранную главу, «Вся инструкция / PDF» — все главы через диалог печати браузера.</p>
<p>Инструкция описывает работу реального прибора, а не имитирует его. Здесь нет кнопок, посылающих команды клапану, датчикам или нагреву. Для работы используйте локальный интерфейс ПарДозора.</p>
""", "памятка словарь термины быстро справка помощь краткая инструкция"),
]
